INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('eu-budget-2028-2034-costa-vorschlag-oesterreich-bauer-sondergipfel','EU-Budget 2028–2034: Österreich fordert mehr Kürzungen','Ratspräsident Costa schlägt für 2028 bis 2034 rund 1,78 Billionen Euro und eine Digitalsteuer vor. Europaministerin Bauer reicht das nicht – sie stellt vor dem Sondergipfel drei Bedingungen.','Das **EU-Budget** für die Jahre 2028 bis 2034 geht in die entscheidende Runde: EU-Ratspräsident António Costa hat am Samstag in Brüssel einen neuen Kompromissvorschlag für den mehrjährigen Finanzrahmen vorgelegt. Österreich reagiert zurückhaltend. Europaministerin Claudia Bauer (ÖVP) sieht darin zwar einen ersten Schritt, aber noch keine ausreichende Kürzung. Am Donnerstag und Freitag beraten die Staats- und Regierungschefs bei einem Sondergipfel über das Papier.

## Was Costas Vorschlag für das EU-Budget vorsieht

Der Entwurf des Ratspräsidenten kommt auf rund 1,781 Billionen Euro für sieben Jahre, gerechnet inklusive geschätzter Inflation bis 2034. Zu Preisen von 2025 entspricht das etwa 1,582 Billionen Euro. Damit liegt Costa rund 204 Milliarden Euro unter dem ursprünglichen Plan der EU-Kommission vom Juli 2025, der knapp zwei Billionen Euro umfasste.

Im Vergleich zur sogenannten Verhandlungsbox der irischen Ratspräsidentschaft vom Oktober fällt die zusätzliche Einsparung allerdings deutlich kleiner aus: Hier beträgt der Abstand nur noch rund 44 Milliarden Euro. Zum Vergleich: Der laufende Finanzrahmen 2021 bis 2027 umfasst etwa 1,2 Billionen Euro.

Laut Costa sollen die direkten nationalen Beiträge der Mitgliedstaaten trotz des höheren Gesamtvolumens kaum steigen, gemessen an der Wirtschaftsleistung von 0,80 auf 0,82 Prozent des Bruttonationaleinkommens. Möglich machen sollen das Wirtschaftswachstum und neue Einnahmen der EU.

## Digitalsteuer als neue Einnahmequelle

Kernstück der neuen Eigenmittel ist eine Digitalabgabe. Große Konzerne sollen drei Prozent auf Umsätze aus Online-Werbung, Plattformdiensten und der Verwertung von Nutzerdaten zahlen. Betroffen wären Unternehmen mit mehr als 50 Millionen Euro Digitalumsatz in der EU und über 750 Millionen Euro Jahresumsatz weltweit. Die Abgabe würde jährlich mehr als fünf Milliarden Euro bringen und eine zuvor diskutierte Abgabe für Großunternehmen ersetzen.

Weitere Punkte des Pakets:

- Abgaben auf Erlöse aus der Vergabe von Mobilfunkfrequenzen werden geprüft.
- Costa lässt Steuern im Bereich Kryptowährungen untersuchen.
- Die Rückzahlung der Corona-Schulden aus dem Aufbaufonds soll in den ersten Jahren langsamer anlaufen.

Insgesamt sollen neue Eigenmittel laut Costa mehr als 60 Milliarden Euro pro Jahr einbringen.

## Österreich: Bedingungen für ein Ja

Für Europaministerin Bauer reicht der Entwurf nicht. Sie vermisst eine deutliche Kürzung und knüpft die österreichische Zustimmung an drei Bedingungen: ein klar kleineres Gesamtvolumen, einen stabilen Beitrag Österreichs und den vollen Beitragsrabatt für alle sieben Jahre. Ohne ernsthafte Verhandlungsgrundlage werde es bis Jahresende keine Einigung geben, ließ Bauer gegenüber der APA wissen. Das lässt sich als indirekte Vetodrohung lesen, denn der Finanzrahmen muss einstimmig beschlossen werden.

Bundeskanzler Christian Stocker (ÖVP) hatte zuletzt beim informellen Gipfel in Dublin gemeinsam mit Deutschland, Dänemark, Schweden und Finnland einen neuen Vorschlag mit spürbar geringerem Volumen verlangt. Die Gruppe der Nettozahler finanziert nach eigenen Angaben fast 40 Prozent des EU-Haushalts. Abgelehnt hat die ÖVP stets Abgaben, die Unternehmen direkt belasten. In der Koalition hatte Finanzminister Markus Marterbauer (SPÖ) mit seiner Offenheit für CORE für Diskussionen gesorgt. Wie sich der Budgetkurs im Inland entwickelt, zeigt die [Schnelleinschätzung des Fiskalrats zu den Staatsschulden](/artikel/staatsschulden-oesterreich-fiskalrat-schnelleinschaetzung-2027).

## Kritik aus Berlin, Paris und dem Europaparlament

Auch andere Hauptstädte sind skeptisch. Das französische Präsidialamt erklärte, der Vorschlag könne keine Grundlage für eine Einigung sein, auch Deutschland lehnt ihn ab. Aus der Gegenrichtung kommt Kritik vom Europäischen Parlament: Dessen Chefverhandler Siegfried Mureșan (EVP) nannte die Kürzungen inakzeptabel, sie würfen die Verhandlungen zurück. Die Länder der Kohäsionsgruppe wiederum wehren sich gegen Einschnitte bei Regional- und Agrarförderungen.

## Wie es jetzt weitergeht

Vor dem Gipfel befasst sich am Mittwoch, 25. November, der EU-Hauptausschuss des Nationalrats mit der österreichischen Linie, so sieht es die Parlamentswoche vor. Am 26. und 27. November treffen sich die Staats- und Regierungschefs in Brüssel. Eine Einigung strebt Costa beim regulären EU-Gipfel im Dezember an. Gelingt ein Abschluss noch 2026, könnten die nötigen Rechtsakte 2027 beschlossen werden, damit ab 2028 ohne Unterbrechung EU-Gelder fließen. Welche Rolle EU-Mittel schon heute für österreichische Programme spielen, zeigt etwa der [Klima-Sozialplan, den die Regierung in Brüssel eingereicht hat](/artikel/klima-sozialplan-oesterreich-eu-einreichung).','politik','Europa',NULL,'news','Presseinfo Redaktion','/assets/img/artikel/eu-budget-2028-2034-costa-vorschlag-oesterreich-bauer-sondergipfel.webp','APA / oe24.at, ZDFheute, Parlamentskorrespondenz','https://www.oe24.at/a/streit-um-eu-budget-costa-kuerzt-nach-kritik-von-nettozahlern-900135201','published','2026-11-23T06:55:00.000Z','2026-11-23T06:55:00.000Z','EU-Budget 2028–2034: Österreich will Kürzungen','EU-Budget 2028–2034: Costa legt neuen Vorschlag mit 1,78 Billionen Euro vor. Warum Österreich mehr Kürzungen fordert und was beim Sondergipfel ansteht.','EU-Budget','["EU-Budget","EU-Budget 2028-2034","mehrjähriger Finanzrahmen","Costa Vorschlag EU-Haushalt","EU-Sondergipfel November 2026","Nettozahler Österreich","Digitalsteuer EU","Claudia Bauer EU-Budget","Beitragsrabatt Österreich"]','EU-Budget: Flaggen und Haushaltsunterlagen vor dem Sondergipfel in Brüssel','Photorealistic wide shot of a row of European Union member state flags in front of a modern glass government building in Brussels on a grey November morning, a stack of budget documents and a calculator on a conference table in the foreground, shallow depth of field, no people, no text, no logos, no readable signs','[{"q":"Wie groß ist Costas Vorschlag für das EU-Budget 2028–2034?","a":"Rund 1,781 Billionen Euro inklusive Inflation, etwa 204 Milliarden Euro weniger als der Kommissionsentwurf von knapp zwei Billionen Euro."},{"q":"Was fordert Österreich?","a":"Ein deutlich kleineres Gesamtvolumen, einen stabilen österreichischen Beitrag und den vollen Beitragsrabatt für alle sieben Jahre."},{"q":"Wann wird entschieden?","a":"Beim Sondergipfel am 26. und 27. November wird beraten, eine Einigung ist für den EU-Gipfel im Dezember angepeilt. Nötig ist Einstimmigkeit."}]',0) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
